          const item = getItem(id)
          const price = Math.max(1, Math.floor((item.price || 10) * 0.5))
          list.append(el('div', { class: 'shop-row' }, [
            itemIcon(id, 36),
            el('div', { class: 'shop-copy' }, [el('strong', {}, `${item.name} ×${count}`), el('p', {}, item.desc)]),
