// ── turn flow ─────────────────────────────────────────────────────────────
doAction(action) {
  if (this.busy || this.destroyed || this.battle.over) return
  const result = this.battle.takeTurn(action)
  const events = result.events || []
  if (!events.length && result.rejected) return
  this.play(events)
