    for (const m of this.playerParty) this.energy.player.set(m.uid, 100)
    for (const m of this.enemies) this.energy.enemy.set(m.uid, 100)
    this.seeded = { player: false, enemy: false }
    this.turn = 0
    this.over = false
    this.result = null
