327:   // ── baked ground ──────────────────────────────────────────────────────────
328:   bakeGround() {
329:     const canvas = document.createElement('canvas')
330:     canvas.width = WORLD_W; canvas.height = WORLD_H
331:     const c = canvas.getContext('2d')
332:     c.imageSmoothingEnabled = false
333:     const pal = Object.fromEntries(BIOME_LIST.map(b => [b.id, b.palette]))
334:     for (let y = 0; y < MAP_H; y++) {
335:       for (let x = 0; x < MAP_W; x++) {
336:         const i = y * MAP_W + x
337:         const biome = BIOME_ORDER[this.biomeGrid[i]]
338:         const terrain = this.terrainGrid[i]
339:         const p = pal[biome] || pal.forest
340:         const px = x * TILE, py = y * TILE
341:         const v = this.variantGrid[i] + Math.floor(hash2(x, y, 3) * 4)
342:         let color
343:         if (terrain === T.OCEAN || terrain === T.WATER) {
344:           color = terrain === T.OCEAN ? '#204868' : p.water
345:           if (biome === 'frozen' && terrain === T.WATER) color = '#a9ddec'
346:         } else if (terrain === T.LAVA) {
347:           color = (v % 2) ? '#d6512c' : '#ef6a2e'
348:         } else if (terrain === T.ICE) {
349:           color = v % 2 ? '#a9d9e8' : '#c2e9f2'
350:         } else if (terrain === T.BRIDGE) {
351:           color = biome === 'celestial' ? '#cbbf98' : '#8a6a48'
352:         } else if (terrain === T.PATH) {
353:           color = v % 3 === 0 ? p.path2 : p.path
354:         } else if (terrain === T.PLAZA) {
355:           color = biome === 'celestial' ? '#ddd5b6' : (v % 2 ? '#b8a47e' : '#c4b18a')
356:         } else if (terrain === T.ASH) {
357:           color = v % 2 ? '#3b3130' : '#453938'
358:         } else {
359:           color = [p.ground, p.ground2, p.ground3, p.ground][v % 4]
360:         }
361:         c.fillStyle = color
362:         c.fillRect(px, py, TILE, TILE)
363: 
364:         // organic tile texture
365:         const seed = hash2(x, y, 57)
366:         if (terrain === T.GROUND) {
367:           if (seed < 0.35) {
368:             c.fillStyle = p.ground2
369:             c.fillRect(px + 3 + Math.floor(seed * 30) % 8, py + 4 + Math.floor(seed * 17) % 7, 3, 2)
370:           }
371:           if (seed > 0.9) {
372:             c.fillStyle = p.ground3
373:             c.fillRect(px + 7, py + 9, 4, 2)
374:           }
375:           if (biome === 'forest' && seed > 0.75) {
376:             c.fillStyle = '#7fcf6f'
377:             c.fillRect(px + 4, py + 11, 1, 2); c.fillStyle = '#a8e88c'; c.fillRect(px + 4, py + 10, 1, 1)
378:           }
379:           if (biome === 'desert' && seed > 0.6) {
380:             c.fillStyle = 'rgba(255,240,190,0.35)'; c.fillRect(px + 2, py + 6, 6, 1)
381:           }
382:           if (biome === 'celestial' && seed > 0.62) {
383:             c.fillStyle = 'rgba(255,248,190,0.5)'; c.fillRect(px + 5, py + 7, 2, 2)
384:           }
385:         }
386:         if ((terrain === T.OCEAN || terrain === T.WATER) && seed > 0.55) {
387:           c.fillStyle = terrain === T.OCEAN ? '#3b6c8c' : 'rgba(220,250,255,0.5)'
388:           const wx = px + 2 + Math.floor(seed * 9)
389:           c.fillRect(wx, py + 4 + Math.floor(seed * 10 % 6), 5, 1)
390:           c.fillRect(wx + 2, py + 9 + Math.floor(seed * 13 % 4), 4, 1)
391:         }
392:         if (terrain === T.LAVA) {
393:           c.fillStyle = '#ffcf6a'
394:           c.fillRect(px + 4, py + 6 + Math.floor(seed * 6), 5, 2)
395:           if (seed > 0.6) c.fillRect(px + 9, py + 2, 2, 3)
396:         }
397:         if (terrain === T.BRIDGE) {
398:           c.fillStyle = 'rgba(45,25,15,0.55)'
399:           for (let k = 0; k < 4; k++) c.fillRect(px, py + k * 4, TILE, 1)
400:           c.fillStyle = '#3f2a1c'
401:           c.fillRect(px, py, 1, TILE); c.fillRect(px + TILE - 1, py, 1, TILE)
402:         }
403:         if (terrain === T.PATH || terrain === T.PLAZA) {
404:           if (seed > 0.6) { c.fillStyle = 'rgba(80,60,40,0.35)'; c.fillRect(px + 3, py + 5, 2, 2); c.fillRect(px + 10, py + 11, 2, 1) }
405:           if (seed < 0.12) { c.fillStyle = 'rgba(255,245,210,0.35)'; c.fillRect(px + 8, py + 7, 1, 1) }
406:         }
407:         // shoreline edges
408:         if (terrain !== T.WATER && terrain !== T.OCEAN && terrain !== T.LAVA) {
409:           const above = this.terrainGrid[(y - 1) * MAP_W + x]
410:           if (above === T.WATER || above === T.OCEAN) { c.fillStyle = 'rgba(240,250,255,0.6)'; c.fillRect(px, py, TILE, 2) }
411:         }
412:       }
413:     }
414:     // Fine details on plaza: mosaic around town centre
415:     for (const t of Object.values(this.towns)) {
416:       const cx = t.x * TILE + 8, cy = t.y * TILE + 8
417:       c.strokeStyle = 'rgba(255,240,200,0.28)'
418:       c.lineWidth = 1
419:       c.beginPath(); c.arc(cx, cy, 5 * TILE, 0, Math.PI * 2); c.stroke()
420:       c.beginPath(); c.arc(cx, cy, 2.4 * TILE, 0, Math.PI * 2); c.stroke()
421:     }
422:     this.mapCanvas = canvas
423:   }
