425:   buildMinimap() {
426:     const canvas = document.createElement('canvas')
427:     canvas.width = MAP_W; canvas.height = MAP_H
428:     const c = canvas.getContext('2d')
429:     for (let y = 0; y < MAP_H; y++) {
430:       for (let x = 0; x < MAP_W; x++) {
431:         const i = y * MAP_W + x
