470:   spawnResources() {
471:     const rng = mulberry32(9981)
472:     for (const b of BIOME_LIST) {
473:       let placed = 0, attempts = 0
474:       while (placed < 9 && attempts++ < 200) {
475:         const x = b.center[0] + Math.round((rng() - 0.5) * 38)
476:         const y = b.center[1] + Math.round((rng() - 0.5) * 32)
477:         if (x < 6 || y < 6 || x >= MAP_W - 6 || y >= MAP_H - 6) continue
478:         if (BIOME_ORDER[this.biomeGrid[y * MAP_W + x]] !== b.id) continue
479:         if (this.isSolidTile(x, y) || this.isSolidTile(x + 1, y)) continue
480:         if (this.nearTown(x, y, 11) || this.nearBoss(x, y, 9)) continue
481:         if (this.resources.some(r => Math.hypot(r.tx - x, r.ty - y) < 4)) continue
482:         const item = pick(b.resources, rng)
483:         this.resources.push({
484:           id: `res_${b.id}_${placed}`,
485:           item,
486:           biome: b.id,
487:           tx: x, ty: y,
488:           x: x * TILE + 8, y: y * TILE + 12,
489:           available: true,
490:           respawnAt: 0,
491:           kind: 'resource',
492:         })
493:         placed++
494:       }
495:     }
496:   }
