501:       const p = this.bossPoints[b.id]
502:       const monster = createMonster(b.boss.species, b.boss.level, { friendship: 50 })
503:       monster.hp = maxHpOf(monster)
504:       this.bosses.push({
505:         id: `boss_${b.id}`, kind: 'boss', biome: b.id,
506:         x: p.x * TILE + 8, y: p.y * TILE + 14,
507:         home: { x: p.x * TILE + 8, y: p.y * TILE + 14 },
508:         monster, speciesId: b.boss.species, bob: Math.random() * 6,
509:         name: `${b.boss.arena} Guardian`, arena: b.boss.arena,
510:       })
511:     }
512:   }
