521:       this.mythics.push({
522:         id: `mythic_${b.id}`, kind: 'mythic', biome: b.id,
523:         x: p.x * TILE + 8, y: p.y * TILE + 14,
524:         home: { x: p.x * TILE + 8, y: p.y * TILE + 14 },
525:         monster, speciesId: b.mythic.species, bob: Math.random() * 6,
526:         name: `${getMonster(b.mythic.species).name} — Mythic`,
527:       })
